// Helper to format large numbers (e.g. 372884439040 -> $372.88B)
function formatMarketCap(num) {
    if (!num) return "N/A";
    if (num >= 1.0e+12) return "$" + (num / 1.0e+12).toFixed(2) + "T";
    if (num >= 1.0e+9) return "$" + (num / 1.0e+9).toFixed(2) + "B";
    if (num >= 1.0e+6) return "$" + (num / 1.0e+6).toFixed(2) + "M";
    return "$" + num;
}

// Aggregate multiple rows (tickers) into a single context object for the AI
const items = $input.all();
if (items.length === 0) return [{json: {error: "No data found"}}];

// Portfolio Metadata
const portfolio = {
  id: items[0].json.portfolio_id,
  name: items[0].json.portfolio_name,
  thesis: items[0].json.thesis || "No thesis provided."
};

// Format Ticker Data (Enhanced with Business Summary & Patents)
const tickers = items.map(item => {
  const i = item.json;

  // --- 1. PARSE FINANCIALS & SUMMARY ---
  const tInfo = i.raw_tickerinfo || {};

  // Handle Summary (Cut off at 600 chars to save tokens but keep context)
  const businessSummary = tInfo.longBusinessSummary 
      ? tInfo.longBusinessSummary.substring(0, 600) + (tInfo.longBusinessSummary.length > 600 ? "..." : "")
      : "No business summary available.";

  const sector = tInfo.sector || "Unknown Sector";
  const mktCap = formatMarketCap(tInfo.marketCap);
  const peRatio = tInfo.forwardPE ? parseFloat(tInfo.forwardPE).toFixed(2) : "N/A";

  // --- 2. PARSE PATENT DATA ---
  let patentSummary = "No patent analysis available";
  if (i.patent_summary) {
      if (typeof i.patent_summary === 'string') {
          patentSummary = i.patent_summary;
      } else if (i.patent_summary.analysis) {
          patentSummary = i.patent_summary.analysis;
      } else {
          // Fallback: Dump object if structure is unknown
          patentSummary = JSON.stringify(i.patent_summary);
      }
  }

  // --- 3. BUILD RICH REPORT ---
  return `
  === REPORT FOR ${i.ticker} (${i.company_name || 'N/A'}) ===

  [1] FINANCIAL CONTEXT
  - Sector: ${sector}
  - Market Cap: ${mktCap} | Forward P/E: ${peRatio}
  - Summary: ${businessSummary}

  [2] QUANTITATIVE PERFORMANCE
  - Return: ${parseFloat(i.total_return_pct || 0).toFixed(2)}%
  - Sharpe Ratio: ${parseFloat(i.sharpe_ratio || 0).toFixed(2)}
  - Max Drawdown: ${parseFloat(i.max_drawdown || 0).toFixed(2)}%
  - Alpha: ${parseFloat(i.alpha || 0).toFixed(4)} | Beta: ${parseFloat(i.beta_market || 0).toFixed(2)}

  [3] IP & INNOVATION (PATENTS)
  - Total Patents: ${i.patent_count || 0}
  - AI Synthesis of IP: ${patentSummary}`;
}).join("\n\n-----------------------------------\n\n");

// Simple Aggregates for Context
// (Added parseFloat to ensure math works even if DB returns strings)
const avgSharpe = items.reduce((sum, item) => sum + (parseFloat(item.json.sharpe_ratio) || 0), 0) / items.length;
const avgReturn = items.reduce((sum, item) => sum + (parseFloat(item.json.total_return_pct) || 0), 0) / items.length;

return [{
  json: {
    portfolio_id: portfolio.id,
    portfolio_name: portfolio.name,
    thesis: portfolio.thesis,
    ticker_count: items.length,
    aggregated_stats: {
      avg_sharpe: avgSharpe.toFixed(2),
      avg_return: avgReturn.toFixed(2) + "%"
    },
    components_context: tickers
  }
}];

// Clean and Parse JSON from AI
const aiText = $json.message.content;

let cleanText = aiText
  .replace(/^```json\s*/i, "")
  .replace(/^```/i, "")
  .replace(/```$/i, "")
  .trim();

let parsed;
try {
  parsed = JSON.parse(cleanText);
} catch (e) {
  throw new Error("Failed to parse AI JSON: " + cleanText);
}

// Pass forward along with ID
return [{
  json: {
    portfolio_id: $('Format Data for AI').item.json.portfolio_id,
    ai_summary: parsed
  }
}];

